  let timer:number; function queueSave(){clearTimeout(timer);timer=window.setTimeout(async()=>{await saveAutosave(doc,assets);status=t("saved");setTimeout(()=>status="",1200)},600);}
  function addLayer(){editingMask=false;const layer=newLayer(locale==="zh-CN"?`图层 ${doc.layers.length+1}`:`Layer ${doc.layers.length+1}`);doc={...doc,layers:[layer,...doc.layers],activeLayerId:layer.id};bufferFor(layer);renderDocument();queueSave();}
  function addText(){editingMask=false;const layer=newLayer(locale==="zh-CN"?"文字":"Text");layer.type="text";layer.text=locale==="zh-CN"?"双击编辑文字":"Double-click to edit";layer.font="sans-serif";layer.fontSize=64;layer.color=color;doc={...doc,layers:[layer,...doc.layers],activeLayerId:layer.id};const c=bufferFor(layer).getContext("2d")!;c.font=`${layer.fontSize}px ${layer.font}`;c.fillStyle=color;c.fillText(layer.text,px.trimX+30,px.trimY+90);commit();}
  function duplicateLayer(){if(!active)return;editingMask=false;const copy=structuredClone(active);copy.id=uid();copy.name+=locale==="zh-CN"?" 副本":" copy";delete copy.linkSourceId;const owner=ownerOf(active);if(owner.assetId)copy.assetId=owner.assetId;const buffer=blankBuffer();buffer.getContext("2d")!.drawImage(bufferFor(active),0,0);layerBuffers.set(copy.id,buffer);copy.bitmap=buffer.toDataURL();if(copy.mask){const mask=blankBuffer();mask.getContext("2d")!.drawImage(maskBufferFor(active),0,0);maskBuffers.set(copy.id,mask);copy.mask.bitmap=mask.toDataURL();}doc={...doc,layers:[copy,...doc.layers],activeLayerId:copy.id};renderDocument();queueSave();}
