  function unlinkActive(){if(!active?.linkSourceId)return;const owner=ownerOf(active),srcBuf=bufferFor(active),buf=blankBuffer();buf.getContext("2d")!.drawImage(srcBuf,0,0);layerBuffers.set(active.id,buf);active.bitmap=buf.toDataURL();if(owner.assetId)active.assetId=owner.assetId;delete active.linkSourceId;boxCache.delete(active.id);doc={...doc,layers:[...doc.layers]};renderDocument();queueSave();}
