  function onLinkChange(event:Event){if(!active)return;const sourceId=(event.target as HTMLSelectElement).value;if(!sourceId){unlinkActive();return;}if(active.linkSourceId===sourceId)return;if(!active.linkSourceId&&active.bitmap){dialog={title:t("link"),message:t("linkOverwrite"),onConfirm:()=>linkActive(sourceId)};return;}linkActive(sourceId);}
  function selectLayer(id:string){editingMask=false;doc={...doc,activeLayerId:id};renderDocument();}
  function selectMask(id:string){editingMask=true;doc={...doc,activeLayerId:id};renderDocument();}
  function toggleLayer(layer:ArtLayer){layer.visible=!layer.visible;editingMask=false;doc={...doc,layers:[...doc.layers],activeLayerId:layer.id};renderDocument();queueSave();}
