  function onLayerDragStart(e:DragEvent,id:string){dragLayerId=id;e.dataTransfer!.effectAllowed="move";e.dataTransfer!.setData("text/plain",id);}
  function onLayerDragOver(e:DragEvent,id:string){if(!dragLayerId)return;e.preventDefault();e.stopPropagation();e.dataTransfer!.dropEffect="move";dropLayerId=id;}
  function onLayerDrop(e:DragEvent,targetId:string){e.preventDefault();e.stopPropagation();const fromId=dragLayerId;dragLayerId=null;dropLayerId=null;if(!fromId||fromId===targetId)return;const layers=[...doc.layers],from=layers.findIndex(l=>l.id===fromId),to=layers.findIndex(l=>l.id===targetId);if(from<0||to<0)return;const [item]=layers.splice(from,1);layers.splice(to,0,item);doc={...doc,layers};renderDocument();queueSave();}
