  function openSettings(){settingsOriginal=structuredClone(doc.spec);showSettings=true;}
  async function cancelSettings(){if(settingsOriginal)doc={...doc,spec:settingsOriginal};showSettings=false;await tick();setupCanvas();}
  async function ingestImage(file:File){if(!file.type.startsWith("image/"))return null;const image=await createImageBitmap(file);const bytes=await file.arrayBuffer(),hash=await crypto.subtle.digest("SHA-256",bytes),id=uid();const checksum=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,"0")).join("");const asset:SourceAsset={id,name:file.name,mime:file.type,width:image.width,height:image.height,checksum,bytes:file};assets.set(id,asset);return {image,asset};}
  function drawImport(layer:ArtLayer,image:ImageBitmap,clear:boolean){const scale=fitImportScale(image.width,image.height,px.width,px.height),b=bufferFor(layer),c=b.getContext("2d")!;if(clear)c.clearRect(0,0,b.width,b.height);c.drawImage(image,(px.width-image.width*scale)/2,(px.height-image.height*scale)/2,image.width*scale,image.height*scale);layer.bitmap=b.toDataURL();}
  async function importImageFile(file:File){const loaded=await ingestImage(file);if(!loaded)return;editingMask=false;const layer=newLayer(file.name);layer.type="image";layer.assetId=loaded.asset.id;doc={...doc,layers:[layer,...doc.layers],activeLayerId:layer.id};drawImport(layer,loaded.image,false);commit();}
  async function replaceLayerContent(file:File){if(!active)return;const loaded=await ingestImage(file);if(!loaded)return;const owner=ownerOf(active),oldAssetId=owner.assetId;checkpointOwner();owner.type="image";owner.assetId=loaded.asset.id;drawImport(owner,loaded.image,true);gcAsset(oldAssetId);commit();}
  async function importImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await importImageFile(file);input.value="";}
  async function onReplaceImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await replaceLayerContent(file);input.value="";}
  function onFileDragOver(e:DragEvent){if(!e.dataTransfer?.types.includes("Files"))return;e.preventDefault();e.dataTransfer.dropEffect="copy";fileDrop=true;}
  function onFileDragLeave(e:DragEvent){const next=e.relatedTarget as Node|null;if(!next||!(e.currentTarget as Node).contains(next))fileDrop=false;}
  async function onFileDrop(e:DragEvent){fileDrop=false;const files=[...e.dataTransfer?.files??[]].filter(f=>f.type.startsWith("image/"));if(!files.length)return;e.preventDefault();for(const file of files.reverse())await importImageFile(file);}
  function addEffect(type:EffectType){if(!active)return;active.effects=[...active.effects,createEffect(type)];doc={...doc,layers:[...doc.layers]};applyEffects();}
  async function applyEffects(){renderDocument();queueSave();}
  function moveEffect(index:number,delta:number){if(!active)return;const n=index+delta;if(n<0||n>=active.effects.length)return;[active.effects[index],active.effects[n]]=[active.effects[n],active.effects[index]];active.effects=[...active.effects];doc={...doc,layers:[...doc.layers]};applyEffects();}
  function removeEffect(index:number){if(!active)return;active.effects=active.effects.filter((_,i)=>i!==index);doc={...doc,layers:[...doc.layers]};applyEffects();}
  function toggleTheme(){const root=document.documentElement,next=root.dataset.theme==="xianii"?"xianii-light":"xianii";root.dataset.theme=next;localStorage.setItem("theme",next);}
  async function toggleLocale(){locale=locale==="zh-CN"?"en":"zh-CN";doc={...doc,locale};localStorage.setItem("locale",locale);await tick();setupCanvas();}
  function fresh(){doc=newDocument(locale);assets=new Map();layerBuffers.clear();maskBuffers.clear();boxCache.clear();patternMemo.v=null;patternLayerId="";history=[];future=[];dialog=null;editingMask=false;view={x:0,y:0};setTimeout(setupCanvas);queueSave();}
  async function saveFile(){download(await exportProject(doc,assets),`${doc.name||"Untitled"}.artmaker`);}
  async function openProject(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const loaded=await importProject(file);doc=loaded.document;assets=new Map(loaded.assets.map(a=>[a.id,a]));locale=doc.locale;editingMask=false;patternLayerId="";patternMemo.v=null;await tick();setupCanvas();await hydrateLayers();queueSave();}
  async function exportPng(){renderDocument({overlay:false});const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(v=>v?resolve(v):reject(),"image/png"));download(blob,`${doc.name||"ArtMaker"}-${px.width}x${px.height}.png`);renderDocument();}
  async function exportPdf(){renderDocument({overlay:false});const rgba=canvas.getContext("2d")!.getImageData(0,0,canvas.width,canvas.height);download(await exportCmykPdf(rgba,doc.spec),`${doc.name||"ArtMaker"}-${px.width}x${px.height}.pdf`);renderDocument();}
  async function updateSpec(){doc={...doc,spec:{...doc.spec,bleed:{...doc.spec.bleed}}};await tick();setupCanvas();queueSave();}
  const zoomLevels=[.1,.125,.16,.2,.25,.33,.4,.5,.67,.8,1,2,3,4];
