  onMount(async()=>{locale=(localStorage.getItem("locale") as typeof locale)||((navigator.language.startsWith("zh"))?"zh-CN":"en");const saved=await loadAutosave();if(saved){doc=saved.document;assets=new Map(saved.assets.map(a=>[a.id,a]));locale=doc.locale;status=t("restore");}setupCanvas();await hydrateLayers();});
</script>

<svelte:window onkeydown={(e)=>{if(e.key==="Escape"){pickingEffectId=null;dialog=null;if(previewing){previewing=false;renderDocument()}}if((e.ctrlKey||e.metaKey)&&e.key==="z"){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key==="s"){e.preventDefault();saveFile()}shapeKey(e)}} onkeyup={shapeKey}/>
{#key locale}
<div class="app-shell" class:dropping={fileDrop} ondragenter={onFileDragOver} ondragover={onFileDragOver} ondragleave={onFileDragLeave} ondrop={onFileDrop}>
  <header class="topbar">
    <div class="brand"><span class="brand-mark">A</span><div><strong>ArtMaker</strong><small>PRINT CANVAS</small></div></div>
    <nav class="menu-actions"><button onclick={fresh}>{t("new")}</button><button onclick={()=>projectInput.click()}>{t("open")}</button><button onclick={saveFile}>{t("save")}</button><span></span><button onclick={()=>fileInput.click()}>{t("import")}</button><button onclick={openSettings}>{t("settings")}</button><span></span><button onclick={undo} disabled={!history.length}>{t("undo")}</button><button onclick={redo} disabled={!future.length}>{t("redo")}</button></nav>
    <div class="header-end"><span class="autosave">{status||`${doc.spec.dpi} DPI · ${px.width} × ${px.height} px`}</span><button class="icon-btn" onclick={toggleTheme} title={t("theme")}>◐</button><button class="lang-btn" onclick={toggleLocale}>{t("lang")}</button><button class:active={previewing} onclick={togglePreview} title={t("previewHint")}>{t("preview")}</button><button onclick={exportPdf} title={t("exportPdfHint")}>{t("exportPdf")}</button><button class="export-btn" onclick={exportPng}>{t("export")}</button></div>
  </header>
  <div class="workspace">
    <aside class="toolrail">
      {#each tools as item}<button class:active={tool===item.id} onclick={()=>tool=item.id} title={locale==="zh-CN"?item.zh:item.en}><b>{item.icon}</b><small>{locale==="zh-CN"?item.zh:item.en}</small></button>{/each}
    </aside>
    <section class="center">
      <div class="contextbar">{#if tool==="select"}<span class="tool-hint">{t("selectHint")}</span>{:else if tool==="eyedropper"}<span class="tool-hint">{t("eyedropperHint")}</span>{:else if tool==="rect"||tool==="ellipse"}<label><span>{t("fill")}</span><input type="color" bind:value={fillColor}/><input class="range" type="range" min="0" max="1" step=".01" bind:value={fillAlpha}/><output>{Math.round(fillAlpha*100)}%</output></label><label><span>{t("stroke")}</span><input type="color" bind:value={strokeColor}/><input class="range" type="range" min="0" max="1" step=".01" bind:value={strokeAlpha}/><output>{Math.round(strokeAlpha*100)}%</output></label><label><span>{t("size")}</span><input class="range" type="range" min="1" max="500" bind:value={size}/><output>{size}px</output></label>{:else if tool==="pattern"}<label><span>{t("patternSource")}</span><select bind:value={patternLayerId}><option value="">{t("patternNone")}</option>{#each doc.layers as layer}<option value={layer.id}>{layer.name}</option>{/each}</select></label>{#if !patternLayerId}<span class="tool-hint">{t("patternHint")}</span>{:else}{@const tile=patternTile()}{#if tile}<output>{tile.w}×{tile.h}px</output>{:else}<span class="tool-hint">{t("patternEmpty")}</span>{/if}{/if}{:else}{#if tool!=="eraser"}<label><span>{t("color")}</span><input type="color" bind:value={color}/></label>{/if}{#if tool!=="fill"}<label><span>{t("size")}</span><input class="range" type="range" min="1" max="500" bind:value={size}/><output>{size}px</output></label>{/if}{#if tool==="brush"||tool==="eraser"}<label><span>{t("shape")}</span><select bind:value={brushShape}><option value="round">{t("shapeRound")}</option><option value="square">{t("shapeSquare")}</option></select></label>{#if brushShape==="round"}<label><span>{t("hardness")}</span><input class="range" type="range" min="0" max="1" step=".01" bind:value={hardness}/><output>{Math.round(hardness*100)}%</output></label>{/if}{/if}{/if}</div>
      <div class="canvas-stage" class:panning class:previewing bind:this={stage} onwheel={wheel} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp} onpointerleave={()=>{if(!drawing&&!panning)cursor.visible=false}}><div class="canvas-wrap" style={wrapStyle}><div class="ruler horizontal">{#each [0,.25,.5,.75,1] as ratio}<span style={`left:${ratio*100}%`}>{Math.round(px.width*ratio)}</span>{/each}</div><div class="ruler vertical">{#each [0,.25,.5,.75,1] as ratio}<span style={`top:${ratio*100}%`}>{Math.round(px.height*ratio)}</span>{/each}</div><canvas class:pixelated={zoom>=1&&Number.isInteger(zoom)} bind:this={canvas}></canvas>{#if tool==="select"&&active&&!active.locked}{@const box=contentBox(active)}{#if box}<div class="layer-frame" style={selectFrameStyle(active,box,zoom)}><i class="bounds"></i>{#each handles as h}<i class="handle {h}" data-handle={h}></i>{/each}</div>{/if}{/if}<div class="trim-guide" style={`left:${px.trimX*zoom}px;top:${px.trimY*zoom}px;width:${px.trimWidth*zoom}px;height:${px.trimHeight*zoom}px`}><span class="guide-badge">{t("trim")}</span></div><div class="safe-guide" style={`left:${(px.trimX+safePx)*zoom}px;top:${(px.trimY+safePx)*zoom}px;width:${(px.trimWidth-safePx*2)*zoom}px;height:${(px.trimHeight-safePx*2)*zoom}px`}><span class="guide-badge">{t("safeGuide")}</span></div>{#if cursor.visible&&(tool==="brush"||tool==="eraser")}<div class="brush-cursor" class:square={brushShape==="square"} style={`left:${cursor.x*zoom}px;top:${cursor.y*zoom}px;width:${Math.max(1,size*zoom)}px;height:${Math.max(1,size*zoom)}px`}></div>{:else if cursor.visible&&tool==="pattern"}{@const tile=patternTile()}{#if tile}<div class="brush-cursor square pattern" class:pixelated={zoom>=1&&Number.isInteger(zoom)} style={`left:${cursor.x*zoom}px;top:${cursor.y*zoom}px;width:${tile.w*zoom}px;height:${tile.h*zoom}px`}><img alt="" src={tile.url}/></div>{/if}{/if}</div><div class="zoom"><button onclick={()=>setZoom(zoomLevels[Math.max(0,zoomLevels.indexOf(zoom)-1)])}>−</button><span>{Math.round(zoom*100)}%</span><button onclick={()=>setZoom(zoomLevels[Math.min(zoomLevels.length-1,zoomLevels.indexOf(zoom)+1)])}>＋</button></div></div>
    </section>
    <aside class="rightbar">
      <section class="panel layer-panel"><div class="panel-title"><b>{t("layers")}</b><div><button onclick={addText}>T</button><button onclick={addLayer}>＋</button></div></div><div class="layer-list">{#each doc.layers as layer (layer.id)}<div class="layer-item" class:selected={!editingMask&&layer.id===doc.activeLayerId} class:off={!layer.visible} class:dragging={dragLayerId===layer.id} class:drop-target={dropLayerId===layer.id} draggable="true" onclick={()=>selectLayer(layer.id)} ondragstart={(e)=>onLayerDragStart(e,layer.id)} ondragover={(e)=>onLayerDragOver(e,layer.id)} ondrop={(e)=>onLayerDrop(e,layer.id)} ondragend={onLayerDragEnd}><span class="vis" onclick={(e)=>{e.stopPropagation();toggleLayer(layer)}}></span><span class="thumb">{layer.type==="image"?"▧":layer.type==="text"?"T":"✦"}</span><span class="layer-name">{layer.name}<small>{layer.linkSourceId?`${t("link")} · ${layerName(layer.linkSourceId)}`:`${layer.type.toUpperCase()} · ${Math.round(layer.opacity*100)}%`}</small></span></div>{#if layer.mask}<div class="layer-item mask-item" class:selected={editingMask&&layer.id===doc.activeLayerId} class:off={!layer.mask.enabled} onclick={()=>selectMask(layer.id)}><span class="vis" onclick={(e)=>{e.stopPropagation();toggleMask(layer)}}></span><span class="thumb">▣</span><span class="layer-name">{t("mask")}<small>{layer.mask.space==="layer"?t("maskSpaceLayer"):t("maskSpaceCanvas")}</small></span></div>{/if}{/each}</div>{#if active}<div class="layer-props"><label>{t("name")} <input class="layer-name-input" type="text" bind:value={active.name} oninput={()=>{doc={...doc,layers:[...doc.layers]};queueSave()}}/></label><label>{t("opacity")} <input type="range" min="0" max="1" step=".01" bind:value={active.opacity} oninput={()=>{renderDocument();queueSave()}}/></label><label>{t("blend")} <select bind:value={active.blendMode} onchange={()=>{renderDocument();queueSave()}}><option value="normal">Normal</option><option value="multiply">Multiply</option><option value="screen">Screen</option><option value="overlay">Overlay</option></select></label><div class="transform-fields"><label>X <input type="number" bind:value={editTr.x} oninput={()=>{renderDocument();queueSave()}}/></label><label>Y <input type="number" bind:value={editTr.y} oninput={()=>{renderDocument();queueSave()}}/></label><label>{t("scaleX")} <input type="number" min="1" value={Math.round(editTr.scaleX*100)} oninput={(e)=>setLayerScale("scaleX",e)}/></label><label>{t("scaleY")} <input type="number" min="1" value={Math.round(editTr.scaleY*100)} oninput={(e)=>setLayerScale("scaleY",e)}/></label></div><label>{t("link")} <select value={active.linkSourceId??""} onchange={onLinkChange}><option value="">{t("linkNone")}</option>{#each linkSources as source}<option value={source.id}>{source.name}</option>{/each}</select></label><div><button onclick={()=>replaceInput.click()}>{t("replace")}</button></div><div><button onclick={duplicateLayer}>{t("duplicate")}</button><button class="danger" onclick={askRemoveLayer}>{t("remove")}</button></div>{#if active.mask}{#if editingMask}<label>{t("maskSpace")} <select value={active.mask.space} onchange={(e)=>setMaskSpace((e.currentTarget as HTMLSelectElement).value as MaskSpace)}><option value="layer">{t("maskSpaceLayer")}</option><option value="canvas">{t("maskSpaceCanvas")}</option></select></label><label class="check-row"><input type="checkbox" bind:checked={showMaskPixels} onchange={()=>renderDocument()}/> {t("showMaskPixels")}</label>{/if}<div><button class="danger" onclick={removeMask}>{t("removeMask")}</button></div>{:else}<div><button onclick={addMask}>{t("addMask")}</button></div>{/if}</div>{/if}</section>
      <section class="panel effects-panel"><div class="panel-title"><b>{t("effects")}</b><button onclick={()=>showEffects=!showEffects}>＋</button></div>{#if showEffects}<div class="effect-picker">{#each effectRegistry as effect}<button onclick={()=>{addEffect(effect.type);showEffects=false}}>{effect.label[locale]}</button>{/each}</div>{/if}{#if active?.effects.length}<div class="effect-list">{#each active.effects as effect,index (effect.id)}<div class="effect-item"><div><input type="checkbox" bind:checked={effect.enabled} onchange={applyEffects}/><b>{effectRegistry.find(x=>x.type===effect.type)?.label[locale]}</b><span><button onclick={()=>moveEffect(index,-1)}>↑</button><button onclick={()=>moveEffect(index,1)}>↓</button><button onclick={()=>removeEffect(index)}>×</button></span></div>{#each Object.entries(effect.params).slice(0,8) as [key,value]}{#if effect.type==="halftone"&&(key==="linkSpacing"||key==="spacingY")}{:else if effect.type==="halftone"&&key==="spacingX"}<div class="spacing-link"><label>spacingX<input type="number" min="1" step="1" value={Number(effect.params.spacingX)} onchange={(e)=>setEffectParam(effect,"spacingX",e)}/></label><button class:active={Boolean(effect.params.linkSpacing)} onclick={()=>toggleHalftoneLink(effect)} title={t("linkSpacing")}>↔</button><label>spacingY<input type="number" min="1" step="1" disabled={Boolean(effect.params.linkSpacing)} value={Number(effect.params.spacingY)} onchange={(e)=>setEffectParam(effect,"spacingY",e)}/></label></div>{:else}<label>{key}{#if typeof value==="boolean"}<input type="checkbox" checked={Boolean(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{:else if key==="sourceColor"}<span class="source-picker"><input type="color" value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}/><button class:active={pickingEffectId===effect.id} onclick={()=>pickingEffectId=pickingEffectId===effect.id?null:effect.id} title={t("pickColor")}>◉</button></span>{:else if /color/i.test(key)||key==="from"||key==="to"}<input type="color" value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{:else if key==="direction"}<select value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}><option value="horizontal">→</option><option value="vertical">↓</option><option value="diagonal-down">↘</option><option value="diagonal-up">↗</option></select>{:else if key==="strength"}<span class="effect-range"><input type="range" min="0" max="1" step=".01" value={Number(value)} oninput={(e)=>setEffectParam(effect,key,e)}/><output>{Math.round(Number(value)*100)}%</output></span>{:else if key==="lightness"}<span class="effect-range"><input type="range" min="-100" max="100" step="1" value={Number(value)} oninput={(e)=>setEffectParam(effect,key,e)}/><output>{Number(value)>0?"+":""}{Math.round(Number(value))}</output></span>{:else}<input type="number" min={key==="dot"||key.startsWith("spacing")?1:0} max={key==="tolerance"||key==="softness"?100:undefined} step="1" value={Number(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{/if}</label>{/if}{/each}</div>{/each}</div>{:else}<p class="empty-effects">{t("empty")}</p>{/if}</section>
    </aside>
  </div>
</div>
{#if showSettings}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)cancelSettings()}}><section class="settings-modal" role="dialog" aria-modal="true" aria-label={t("settings")}><div class="panel-title"><b>{t("settings")}</b><button onclick={cancelSettings}>×</button></div><div class="field-grid"><label>{t("width")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.width}/></label><label>{t("height")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.height}/></label><label>{t("dpi")}<input type="number" min="72" max="2400" bind:value={doc.spec.dpi}/></label><label>{t("unit")}<select bind:value={doc.spec.unit}><option value="mm">mm</option><option value="inch">inch</option></select></label></div><div class="wide-field">{t("bleed")} ({doc.spec.unit})<div class="bleed-row">{#each bleedSides as side}<label>{t(side.key)}<input aria-label={t(side.key)} type="number" value={doc.spec.bleed[side.id]} onchange={(e)=>{doc.spec.bleed[side.id]=Number(e.currentTarget.value);doc={...doc}}}/></label>{/each}</div></div><label class="wide-field">{t("safe")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.safeMargin}/></label><div class="pixel-card"><small>{t("pixel")}</small><strong>{px.width.toLocaleString()} × {px.height.toLocaleString()} px</strong><span>≈ {Math.round(px.width*px.height*4/1024/1024)} MB RGBA</span></div><footer><button onclick={cancelSettings}>{t("cancel")}</button><button class="apply" onclick={async()=>{await updateSpec();settingsOriginal=null;showSettings=false}}>{t("apply")}</button></footer></section></div>{/if}
{#if dialog}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)dialog=null}}><section class="settings-modal confirm-modal" role="dialog" aria-modal="true" aria-label={dialog.title}><div class="panel-title"><b>{dialog.title}</b><button onclick={()=>dialog=null}>×</button></div><p class="confirm-copy">{dialog.message}</p><footer><button onclick={()=>dialog=null}>{t("cancel")}</button><button class={dialog.danger?"danger":"apply"} onclick={()=>{const action=dialog!.onConfirm;dialog=null;action();}}>{t("confirm")}</button></footer></section></div>{/if}
<input class="hidden" bind:this={fileInput} type="file" accept="image/png,image/jpeg,image/webp" onchange={importImage}/><input class="hidden" bind:this={replaceInput} type="file" accept="image/png,image/jpeg,image/webp" onchange={onReplaceImage}/><input class="hidden" bind:this={projectInput} type="file" accept=".artmaker" onchange={openProject}/>
{/key}
